  "inlineSchema": "// Esquema de base de datos de Tendia.\n// Pensado para escalar a multi-tenant: muchos Comercios, cada uno con\n// sus propios usuarios \"comerciante\" (dueños/staff) y \"cliente\" (compradores).\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\" // en producción: Postgres (Neon, Supabase, RDS, etc.)\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  COMERCIANTE\n  CLIENTE\n}\n\nmodel Comercio {\n  id        String   @id @default(uuid())\n  nombre    String\n  categoria String?\n  createdAt DateTime @default(now())\n\n  // Identificadores que Meta usa para enrutar un mensaje entrante hacia\n  // este comercio (cada negocio conecta su propio número/página).\n  whatsappPhoneNumberId String? @unique\n  instagramPageId       String? @unique\n\n  // Logo del negocio, guardado como imagen en base64 (data URI).\n  logo String?\n\n  // Cobros: tasa del día (Bs por USD, para Pago Móvil) y datos donde el\n  // cliente debe pagar (JSON validado al guardar: pago_movil / zelle / binance).\n  tasaBs            Float?\n  tasaBsActualizada DateTime?\n  metodosPago       String?\n\n  // Usuarios con rol COMERCIANTE que administran este negocio (dueño, staff)\n  staff Usuario[] @relation(\"StaffDeComercio\")\n\n  // Relación muchos-a-muchos: un cliente puede comprarle a varios comercios\n  clientes       ClienteComercio[]\n  productos      Producto[]\n  pedidos        Pedido[]\n  conversaciones Conversacion[]\n}\n\n// Estado de una conversación activa del agente de IA con un cliente en un\n// canal (WhatsApp/Instagram). Guarda el carrito en curso para que el\n// cliente pueda ir agregando productos mensaje a mensaje.\nmodel Conversacion {\n  id             String   @id @default(uuid())\n  comercioId     String\n  comercio       Comercio @relation(fields: [comercioId], references: [id])\n  telefono       String // número de WhatsApp o PSID de Instagram\n  canal          String // \"whatsapp\" | \"instagram\"\n  estado         String   @default(\"inicio\") // inicio | viendo_menu | armando_pedido\n  carritoJson    String   @default(\"[]\")\n  ultimoMenuJson String   @default(\"[]\")\n  updatedAt      DateTime @updatedAt\n  createdAt      DateTime @default(now())\n\n  @@unique([comercioId, telefono, canal])\n}\n\nmodel Usuario {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  telefono     String?\n  passwordHash String\n  nombre       String\n  role         Role\n  createdAt    DateTime @default(now())\n\n  // Recuperación de contraseña: token de un solo uso con vencimiento.\n  resetToken       String?   @unique\n  resetTokenExpira DateTime?\n\n  // Solo aplica si role = COMERCIANTE\n  comercioId String?\n  comercio   Comercio? @relation(\"StaffDeComercio\", fields: [comercioId], references: [id])\n\n  // Solo aplica si role = CLIENTE\n  comerciosDondeCompra ClienteComercio[]\n  pedidos              Pedido[]\n}\n\n// Tabla puente: relación cliente <-> comercio (para que un cliente pueda\n// tener historial en varios negocios distintos sin duplicar su cuenta).\nmodel ClienteComercio {\n  id            String   @id @default(uuid())\n  clienteId     String\n  cliente       Usuario  @relation(fields: [clienteId], references: [id])\n  comercioId    String\n  comercio      Comercio @relation(fields: [comercioId], references: [id])\n  totalComprado Int      @default(0)\n  createdAt     DateTime @default(now())\n\n  @@unique([clienteId, comercioId])\n}\n\nmodel Producto {\n  id          String   @id @default(uuid())\n  comercioId  String\n  comercio    Comercio @relation(fields: [comercioId], references: [id])\n  nombre      String\n  categoria   String?\n  precio      Int\n  precioAntes Int?\n  promo       String?\n  stock       Int      @default(0)\n  imagen1     String? // foto del producto, guardada como imagen en base64 (data URI)\n  imagen2     String?\n  createdAt   DateTime @default(now())\n}\n\nmodel Pedido {\n  id         String   @id @default(uuid())\n  comercioId String\n  comercio   Comercio @relation(fields: [comercioId], references: [id])\n  clienteId  String\n  cliente    Usuario  @relation(fields: [clienteId], references: [id])\n  items      String // JSON serializado con productos y cantidades\n  total      Int\n  estado     String   @default(\"nuevo\") // nuevo | proceso | listo | entregado | cancelado\n  // pendiente | por_verificar | pagado | rechazado | reembolso_pendiente | reembolsado\n  estadoPago String   @default(\"pendiente\")\n  canal      String   @default(\"web\") // web | whatsapp | instagram | marketplace\n  createdAt  DateTime @default(now())\n  pagos      Pago[]\n}\n\n// Cada declaración de pago del cliente. Registro de auditoría: NUNCA se borra.\n// Montos: montoUsd en centavos de USD; montoBs en céntimos de Bs (solo Pago Móvil).\nmodel Pago {\n  id            String    @id @default(uuid())\n  pedidoId      String\n  pedido        Pedido    @relation(fields: [pedidoId], references: [id])\n  comercioId    String\n  clienteId     String\n  metodo        String // pago_movil | zelle | binance\n  montoUsd      Int\n  montoBs       Int?\n  tasaBs        Float?\n  referencia    String // referencia/confirmación que reporta el cliente (normalizada)\n  comprobante   String? // captura del pago (imagen base64), opcional\n  estado        String    @default(\"por_verificar\") // por_verificar | aprobado | rechazado\n  motivoRechazo String?\n  verificadoPor String?\n  verificadoEn  DateTime?\n  // Evita reutilizar el mismo comprobante: única mientras el pago esté activo\n  // (por_verificar/aprobado); se libera (null) al rechazarse.\n  claveUnica    String?   @unique\n  canal         String    @default(\"web\")\n  createdAt     DateTime  @default(now())\n\n  @@index([comercioId, estado])\n  @@index([pedidoId])\n}\n",
  "inlineSchemaHash": "54a875e882ff2150d99df4ccdb6a476b05af3e95a8e1dae416472ff0f27c51e0",
